from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
images=[
 {'id':'met-storage','title':'Apache storage basket, ca. 1890','file':'home-apache-storage-basket-met.webp','source':'https://www.metmuseum.org/art/collection/search/751527','credit':'Apache artist, name unrecorded; specific Apache nation not identified. The Metropolitan Museum of Art, Diker Collection, gift of Charles and Valerie Diker, 2019.','rights':'CC0 / Public Domain','rightsUrl':'https://creativecommons.org/publicdomain/zero/1.0/','scope':'Museum record and image inspected; photograph shown proportionally. Photographer not individually recorded.'},
 {'id':'curtis-still-life','title':'Apache still life [A], c. 1907','file':'apache-still-life-curtis-1907.jpg','source':'https://www.loc.gov/pictures/item/2002695462/','credit':'Edward S. Curtis. Library of Congress, Prints and Photographs Division, LC-USZ62-130198. A staged grouping of nine containers; individual makers and specific community are not identified in the record.','rights':'No known restrictions on publication','rightsUrl':'https://www.loc.gov/pictures/item/2002695462/','scope':'Full catalogue body and full digital image inspected. Digital image is a copy-negative reproduction, not the original print.'},
 {'id':'usgs-attributed','title':'Basket, attributed to Apache','file':'apache-attributed-basket-usgs.jpg','source':'https://www.usgs.gov/media/images/native-american-basket-ca-1800-jw-powell-collection','credit':'Photograph: USGS Museum Staff. J. W. Powell Collection, USGS-575123. USGS says probably made by Apache and probably acquired by Powell in the 1880s. Its catalogue title gives ca. 1800; this is not a securely established making date.','rights':'Public Domain','rightsUrl':'https://www.usgs.gov/media/images/native-american-basket-ca-1800-jw-powell-collection','scope':'Source record and full digital photograph inspected; uncertain attribution retained.'}
]
(root/'data/apache-collage-images.json').write_text(json.dumps({'reviewedAt':'2026-10-24','scope':'Apache umbrella profile only. These objects do not stand for every Apache nation. No generated imagery or invented cultural motifs. Neutral CSS gradients fill gaps; photographs remain authentic.','images':images},indent=2)+'\n',encoding='utf-8')
p=root/'build.mjs'
s=p.read_text(encoding='utf-8')
s=s.replace("function document(title,description,content,base='',active='directory'){return", "function document(title,description,content,base='',active='directory'){const apache=title==='Apache'&&base==='../../';return",1)
s=s.replace('styles.css?v=profile-maps-1','styles.css?v=apache-collage-1')
s=s.replace('<body>${header(base,active)}','<body${apache?\' class="apache-collage-page"\':\'\'}>${apache?\'<div class="apache-collage-backdrop" aria-hidden="true"></div>\':\'\'}${header(base,active)}',1)
banner='''${p.originalId===16?`<div class="apache-collage-intro" aria-label="Apache material culture photographs"><figure class="collage-met"><img src="../../assets/home-apache-storage-basket-met.webp" alt="Tall Apache storage basket with dark geometric weaving, ca. 1890"><figcaption>Apache storage basket · The Met</figcaption></figure><figure class="collage-curtis"><img src="../../assets/apache-still-life-curtis-1907.jpg" alt="Edward Curtis photograph of nine baskets, bowls and jars arranged as an Apache still life"><figcaption>Edward S. Curtis · c. 1907 · Library of Congress</figcaption></figure><figure class="collage-usgs"><img src="../../assets/apache-attributed-basket-usgs.jpg" alt="Shallow patterned basket attributed, with uncertainty, to Apache makers by the USGS"><figcaption>Attributed to Apache · USGS Museum Staff</figcaption></figure><a class="collage-credit-link" href="#apache-image-credits">Photographs &amp; credits ↓</a></div>`:''}'''
needle='<section class="profile-hero ${p.originalId===16?\'apache-basket-hero\':\'\'}">'
assert needle in s
s=s.replace(needle,banner+needle,1)
start=s.index('${p.originalId===16?"<p class=\\"apache-basket-credit')
end=s.index('${sections}',start)
credit='''${p.originalId===16?`<details class="apache-image-credits" id="apache-image-credits"><summary>Backdrop photographs &amp; credits</summary><p>Publicly available object photographs connected to the broad Apache entry. Individual objects are not representative of every Apache nation.</p>${apacheCollage.images.map(image=>`<p><strong>${e(image.title)}</strong> — ${e(image.credit)} <a href="${e(image.source)}" target="_blank" rel="noopener noreferrer">Source &amp; image record</a> · <a href="${e(image.rightsUrl)}" target="_blank" rel="noopener noreferrer">${e(image.rights)}</a>. <span>${e(image.scope)}</span></p>`).join('')}<p>Image records and photographs reviewed October 24, 2026. Layout uses neutral earth-toned gradients; no generated cultural imagery.</p></details>`:''}'''
s=s[:start]+credit+s[end:]
s=s.replace("const partial=process.argv.includes('--partial');", "const partial=process.argv.includes('--partial');\nconst apacheCollage=JSON.parse(fs.readFileSync(path.join(cwd,'data/apache-collage-images.json'),'utf8'));")
p.write_text(s,encoding='utf-8')
